type Step<T> = { done: true; value: T } | { done: false; next: () => Step<T> };

function even(n: number): Step<boolean> { return n === 0 ? { done: true, value: true } : { done: false, next: () => odd(n - 1) }; }
function odd(n: number): Step<boolean>  { return n === 0 ? { done: true, value: false } : { done: false, next: () => even(n - 1) }; }

function run<T>(s: Step<T>): T {
    while (!s.done) s = s.next();
    return s.value;
}

