type Step<T> = { done: true; value: T } | { done: false; next: () => Step<T> };
type StepGen<T> = Generator<StepGen<T>, T, T>;

function* even(n: number): StepGen<boolean> { return n === 0 ? true : yield odd(n - 1); }
function* odd(n: number): StepGen<boolean>  { return n === 0 ? false : yield even(n - 1); }

function run<T>(gen: StepGen<T>): T {
    const stack: StepGen<T>[] = [gen];
    let out!: T;
    while (stack.length) {
        const r = stack[stack.length - 1].next(out);
        if (r.done) { stack.pop(); out = r.value; } else stack.push(r.value);
    }
    return out;
}
